import{_ as r,o,c as s,a2 as n}from"./chunks/framework.G0y0PQA7.js";const c=JSON.parse('{"title":"모델 메뉴","description":"","frontmatter":{},"headers":[],"relativePath":"features/model.md","filePath":"features/model.md"}'),a={name:"features/model.md"};function e(g,t,d,l,i,h){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="모델-메뉴" tabindex="-1">모델 메뉴 <a class="header-anchor" href="#모델-메뉴" aria-label="Permalink to &quot;모델 메뉴&quot;">​</a></h1><p>모델 메뉴에서 여는 창 — 단어 사전, 그룹·글로벌 그룹, 시퀀스·트리거·테이블스페이스, 옵션, 변경 내역, 번역 관리, 테스트 데이터, 모델 특성 — 의 항목을 설명합니다. 같은 명령은 캔버스 오른쪽 클릭 › 문서 ▸에도 있습니다.</p><p>테이블·컬럼·뷰·관계처럼 캔버스의 대상을 고치는 창은 <a href="/relio/features/dialogs">정보 창</a>에 있습니다.</p><h2 id="메뉴-항목" tabindex="-1">메뉴 항목 <a class="header-anchor" href="#메뉴-항목" aria-label="Permalink to &quot;메뉴 항목&quot;">​</a></h2><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>하는 일</th></tr></thead><tbody><tr><td>모델 › 카테고리 ▸</td><td>카테고리 관리…, 참조하는 테이블 보기 — <a href="/relio/features/categories">카테고리</a></td></tr><tr><td>모델 › 그룹 관리…</td><td>이 문서의 컬럼 그룹</td></tr><tr><td>모델 › 글로벌 그룹 관리…</td><td>여러 파일이 함께 쓰는 컬럼 그룹</td></tr><tr><td>모델 › 단어 사전…</td><td>단어 목록과 정리</td></tr><tr><td>모델 › 변경 내역…</td><td>그 시점 사본 남기기·보기·비교·되돌리기</td></tr><tr><td>모델 › 번역 관리…</td><td>이 문서에서 쓸 번역 사전</td></tr><tr><td>모델 › 테스트 데이터…</td><td>테스트 데이터 만들기·편집</td></tr><tr><td>모델 › 트리거 추가… · 시퀀스 추가… · 테이블스페이스 추가…</td><td>새 객체(시퀀스·테이블스페이스는 지원하는 DB에서만)</td></tr><tr><td>모델 › 옵션…</td><td>DB·대상 버전, 테이블스페이스 환경, 새 테이블 기본값, 검사 옵션</td></tr><tr><td>모델 › 모델 특성…</td><td>스탬프에 나오는 항목</td></tr></tbody></table><h2 id="단어-사전·단어-정보" tabindex="-1">단어 사전·단어 정보 <a class="header-anchor" href="#단어-사전·단어-정보" aria-label="Permalink to &quot;단어 사전·단어 정보&quot;">​</a></h2><ul><li><strong>단어 사전</strong> 창은 단어 목록과 <strong>쓰는 컬럼</strong> 수를 보여 줍니다. <strong>이름으로 찾기</strong>로 거르고, <strong>쓰지 않는 단어만</strong>으로 아무 컬럼도 쓰지 않는 단어만 봅니다. <strong>쓰지 않는 단어 모두 고르기</strong> 뒤 <strong>쓰지 않는 단어 정리</strong>로 한꺼번에 지웁니다(되돌리기 가능). 줄을 더블클릭하면 단어 정보가 열립니다.</li><li><strong>단어 정보</strong> 창은 물리명 · 논리명 · 형식 · 길이 · 소수 · enum/set 인수 · 설명을 고칩니다. 고치면 이 단어를 쓰는 모든 컬럼에 반영된다는 안내와, 쓰는 컬럼 목록(더블클릭하면 캔버스에서 그 컬럼으로 감)이 함께 보입니다.</li></ul><h2 id="그룹-관리·글로벌-그룹-관리" tabindex="-1">그룹 관리·글로벌 그룹 관리 <a class="header-anchor" href="#그룹-관리·글로벌-그룹-관리" aria-label="Permalink to &quot;그룹 관리·글로벌 그룹 관리&quot;">​</a></h2><p>그룹은 여러 테이블이 함께 쓰는 컬럼 묶음입니다(예: 등록일·수정자 같은 공통 컬럼).</p><ul><li>왼쪽 그룹 목록에서 <strong>추가</strong> · <strong>편집</strong> · <strong>삭제</strong>, 오른쪽에서 <strong>그룹명</strong>과 그룹 컬럼 표(추가·편집·삭제·순서·간편 등록)를 고친 뒤 <strong>업데이트</strong>를 누릅니다.</li><li>그룹을 고치면 그 그룹을 쓰는 모든 테이블에 반영됩니다. 쓰는 테이블이 있는 그룹을 지우면 그 목록을 보여 주고 계속할지 묻습니다.</li><li><strong>글로벌 그룹에 추가</strong>는 문서의 그룹을 이 PC의 글로벌 그룹으로 복사합니다. 글로벌 그룹 관리 창의 <strong>문서에 넣기</strong>는 글로벌 그룹을 이 문서의 그룹으로 복사합니다(그 뒤로는 따로 갑니다). 이름이 겹치면 <strong>이름 바꿔 추가</strong>를 묻습니다.</li><li>새 다이어그램을 만들면 글로벌 그룹 전체가 문서 그룹으로 들어갑니다.</li></ul><h2 id="시퀀스·트리거·테이블스페이스" tabindex="-1">시퀀스·트리거·테이블스페이스 <a class="header-anchor" href="#시퀀스·트리거·테이블스페이스" aria-label="Permalink to &quot;시퀀스·트리거·테이블스페이스&quot;">​</a></h2><p>아웃라인에서 오른쪽 클릭이나 <strong>+ 추가</strong>, 또는 모델 메뉴로 만들고, 더블클릭으로 고칩니다.</p><ul><li><strong>시퀀스 정보</strong> — 시퀀스명 · 스키마 · 증가 · 시작 · 최솟값 · 최댓값 · 캐시(캐시 없음) · 순환(CYCLE) · 설명. DB에 따라 데이터 형식·자릿수(DECIMAL만)·순서(ORDER)가 더해집니다. 64비트를 넘는 값도 쓸 수 있습니다. 시퀀스를 지원하지 않는 DB(MySQL·SQLite·MS Access 등)에서는 만들 수 없습니다.</li><li><strong>트리거 정보</strong> — 트리거명 · 스키마 · SQL(CREATE TRIGGER 이름 뒤에 그대로 붙습니다) · 설명. PostgreSQL은 트리거 이름에 스키마를 붙일 수 없어 DDL에서 빼고 씁니다.</li><li><strong>테이블스페이스 정보</strong> — 위에서 <strong>환경</strong>을 고르고 <strong>이름</strong>을 넣습니다. 아래 칸은 DB마다 다릅니다(MySQL 데이터 파일·로그 파일 그룹·스토리지 엔진, Oracle 데이터 파일·파일 크기·자동 확장, DB2 유형·페이지 크기·관리 방식·컨테이너·버퍼 풀, PostgreSQL 위치(location)·소유자, SQL Server 파일 그룹 이름·파일 경로·크기). 속성은 환경마다 따로 저장됩니다.</li></ul><h2 id="옵션" tabindex="-1">옵션 <a class="header-anchor" href="#옵션" aria-label="Permalink to &quot;옵션&quot;">​</a></h2><p>모델 › 옵션…(또는 상태 표시줄 맨 왼쪽 대상 DB 칸)에서 문서 설정을 바꿉니다.</p><table tabindex="0"><thead><tr><th>탭</th><th>내용</th></tr></thead><tbody><tr><td>데이터베이스</td><td>DB, <strong>대상 제품</strong>, <strong>대상 버전</strong>. DB를 바꾸면 &quot;다른 DB 전용 설정은 보존되지만 새 DB에서는 쓰이지 않습니다&quot;를 알리고 확인을 받습니다(되돌리기 가능). 대상 버전은 이 PC에만 기억됩니다.</td></tr><tr><td>테이블스페이스 환경</td><td>환경 목록(예: 운영 DB)과 <strong>추가</strong> · <strong>편집</strong> · <strong>삭제</strong>. 마지막 환경은 지울 수 없고, 환경을 지우면 그 환경의 테이블스페이스 속성도 지워집니다.</td></tr><tr><td>고급 설정</td><td>새 테이블을 만들 때의 기본값(스키마·테이블스페이스, MySQL이면 스토리지 엔진·문자 집합 등).</td></tr><tr><td>옵션</td><td><strong>입력 포커스 이동 시 IME 모드 자동 전환</strong> · <strong>물리명에 쓸 수 있는 문자 검사</strong> · <strong>곡선(Bezier) 사용</strong> · <strong>검증 끄기</strong></td></tr></tbody></table><h2 id="변경-내역" tabindex="-1">변경 내역 <a class="header-anchor" href="#변경-내역" aria-label="Permalink to &quot;변경 내역&quot;">​</a></h2><p>모델 › 변경 내역…은 지금 다이어그램 전체의 사본을 날짜와 함께 문서 안에 남깁니다.</p><ul><li><strong>변경 내용</strong>에 무엇을 바꿨는지 짧게 적고 <strong>추가</strong>, 고르고 <strong>업데이트</strong> · <strong>삭제</strong>.</li><li><strong>이 날짜 데이터 보기</strong> — 그 시점 사본을 읽기 전용 미리보기 탭으로 엽니다.</li><li><strong>이 시점으로 되돌리기</strong> — 문서 내용을 그 시점 사본으로 바꿉니다(되돌리기 가능).</li><li><strong>변경 내용 비교</strong> — 고른 변경 내역(A)과 지금 문서(B)를 비교 탭으로 엽니다. <a href="/relio/features/git#비교-화면">Git과 합치기 › 비교 화면</a></li><li>변경 내역마다 다이어그램 전체 사본이 들어가 파일이 커집니다. 창 아래에 개수와 대략의 크기가 나옵니다.</li></ul><h2 id="번역-관리" tabindex="-1">번역 관리 <a class="header-anchor" href="#번역-관리" aria-label="Permalink to &quot;번역 관리&quot;">​</a></h2><p>모델 › 번역 관리…에서 <strong>가져오기할 때 번역 기능 사용</strong>을 켜고, 이 문서에서 쓸 번역 사전을 체크합니다(위에 있는 사전이 먼저). 사전 목록 자체는 이 PC의 앱 설정에 있고 <strong>사전 파일 추가…</strong> · <strong>사전 관리…</strong> · <strong>목록에서 빼기</strong>로 다룹니다. 번역 사전 파일은 UTF-8 글 파일로, 한 줄에 &quot;원어,번역어&quot;를 씁니다. DB에서 가져올 때 논리명을 채우는 데 쓰입니다. <a href="/relio/features/preferences#번역-사전">환경 설정 › 번역 사전</a></p><h2 id="테스트-데이터" tabindex="-1">테스트 데이터 <a class="header-anchor" href="#테스트-데이터" aria-label="Permalink to &quot;테스트 데이터&quot;">​</a></h2><p>모델 › 테스트 데이터…의 왼쪽 목록에서 <strong>추가</strong> · <strong>편집</strong> · <strong>삭제</strong> · <strong>복사</strong> · <strong>출력</strong>을 합니다. 오른쪽에는 고른 데이터의 테이블명과 레코드 수가 보입니다. <strong>출력</strong>은 고친 내용을 먼저 적용하고 <a href="/relio/features/export#테스트-데이터">테스트 데이터 내보내기</a> 창을 엽니다.</p><p><strong>테스트 데이터 편집</strong> 창:</p><ul><li><strong>이름</strong>, 왼쪽 <strong>모든 테이블</strong> ⇄ 오른쪽 <strong>데이터를 만들 테이블 (레코드 수)</strong>(추가 ▶ / ◀ 빼기).</li><li><strong>출력 순서</strong> — 직접 입력 → 반복 입력, 또는 반복 입력 → 직접 입력.</li><li><strong>직접 입력</strong> 탭 — 표에 값을 직접 넣습니다. 붙여넣기도 됩니다.</li><li><strong>반복 입력</strong> 탭 — 레코드 수를 정하고, 컬럼 머리글을 눌러 <strong>반복 조건</strong>을 정합니다: <strong>반복 유형</strong>(NULL · 포맷 · 열거 · 외래 키(모델에 있는 값)), <strong>반복 수</strong>(같은 값을 몇 행씩), 포맷(<code>%</code>가 숫자로 바뀝니다), 시작 · 끝 · 증분, 열거 값. 미리보기에서 행을 누르면 그 행만 <strong>수정값</strong>을 지정합니다.</li></ul><h2 id="모델-특성" tabindex="-1">모델 특성 <a class="header-anchor" href="#모델-특성" aria-label="Permalink to &quot;모델 특성&quot;">​</a></h2><p>모델 › 모델 특성… 또는 스탬프를 더블클릭합니다. <strong>항목명</strong> · <strong>값</strong> 표(프로젝트명·모델명·버전·회사명·작성자 등)에 <strong>새 항목</strong>을 더하고 지웁니다. <strong>작성일시</strong>·<strong>갱신일시</strong>는 저장할 때 자동으로 채워집니다. 보기 › 스탬프 표시를 켜면 캔버스에 표로 보입니다.</p>',27)])])}const p=r(a,[["render",e]]);export{c as __pageData,p as default};
